/*
 * Spektrafilm for Android — Material Symbols (Outlined, weight 400, 24px). GPLv3 app;
 * the symbol paths are Google's Material Symbols, Apache License 2.0
 * (https://github.com/google/material-design-icons). Film modeling powered by spektrafilm.
 *
 * The exact glyphs the Pen board uses ("Whole app proposed"), as ImageVectors so the app ships
 * no icon font. Generated from the upstream SVGs: viewBox 0 -960 960 960, so each path sits in
 * a group moved down by 960.
 */
package com.spectrafilm.app

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.PathParser
import androidx.compose.ui.unit.dp

/**
 * [viewport] is the SVG's viewBox size: 960 for the current upstream files (viewBox
 * 0 -960 960 960, so the path is moved down by 960), 24 for the few still published on the
 * older 0 0 24 24 grid.
 */
private fun symbol(
    name: String,
    path: String,
    autoMirror: Boolean = false,
    viewport: Float = 960f,
): ImageVector =
    ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = viewport,
        viewportHeight = viewport,
        autoMirror = autoMirror,
    ).addGroup(translationY = if (viewport == 960f) 960f else 0f)
        .addPath(PathParser().parsePathString(path).toNodes(), fill = SolidColor(Color.Black))
        .clearGroup()
        .build()

